/* «مشكاة النبوة» — 300 حديث مشكول (نسخة مدمجة). التفعيل والمناسبة يُقرآن من ورقة «مشكاة النبوة» في جدول بنك التهاني */
window.MK_HADITH=[{"n":1,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ","text":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ","nar":"عن عمر بن الخطاب رضي الله عنه","src":"رواه البخاري (1) ومسلم (1907)","grade":"","occ":"","on":"نعم"},{"n":2,"cat":"العقيدة والإيمان","head":"قال عمر بن الخطاب رضي الله عنه: بينما نحن عند رسول الله ﷺ إذ طلع علينا رجل… فقال: يا محمد، أخبرني عن الإسلام","text":"الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا. قَالَ: فَأَخْبِرْنِي عَنِ الْإِيمَانِ، قَالَ: أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قَالَ: فَأَخْبِرْنِي عَنِ الْإِحْسَانِ، قَالَ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ","nar":"","src":"رواه مسلم (8)","grade":"","occ":"","on":"لا"},{"n":3,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ","nar":"عن ابن عمر رضي الله عنهما","src":"رواه البخاري (8) ومسلم (16)","grade":"","occ":"","on":"نعم"},{"n":4,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَشَقِيٌّ أَوْ سَعِيدٌ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه البخاري (3208) ومسلم (2643)","grade":"","occ":"","on":"نعم"},{"n":5,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ","nar":"عن عائشة رضي الله عنها","src":"رواه البخاري (2697) ومسلم (1718)","grade":"","occ":"","on":"نعم"},{"n":6,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"إِنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ","nar":"عن النعمان بن بشير رضي الله عنهما","src":"رواه البخاري (52) ومسلم (1599)","grade":"","occ":"","on":"لا"},{"n":7,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ","nar":"عن تميم الداري رضي الله عنه","src":"رواه مسلم (55)","grade":"","occ":"","on":"نعم"},{"n":8,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى","nar":"عن ابن عمر رضي الله عنهما","src":"رواه البخاري (25) ومسلم (22)","grade":"","occ":"","on":"لا"},{"n":9,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (7288) ومسلم (1337)","grade":"","occ":"","on":"نعم"},{"n":10,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ… ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ، أَشْعَثَ أَغْبَرَ، يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ: يَا رَبِّ، يَا رَبِّ، وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لِذَلِكَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (1015)","grade":"","occ":"","on":"نعم"},{"n":11,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ","nar":"عن الحسن بن علي رضي الله عنهما","src":"رواه الترمذي (2518) والنسائي (5711)","grade":"صحيح","occ":"","on":"نعم"},{"n":12,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه الترمذي (2317) وابن ماجه (3976)","grade":"حسن صحيح","occ":"","on":"نعم"},{"n":13,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (13) ومسلم (45)","grade":"","occ":"","on":"نعم"},{"n":14,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ","nar":"عن ابن مسعود رضي الله عنه","src":"رواه البخاري (6878) ومسلم (1676)","grade":"","occ":"","on":"لا"},{"n":15,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6018) ومسلم (47)","grade":"","occ":"","on":"نعم"},{"n":16,"cat":"الأخلاق والآداب","head":"عن أبي هريرة رضي الله عنه أن رجلًا قال للنبي ﷺ: أوصني","text":"لَا تَغْضَبْ. فَرَدَّدَ مِرَارًا، قَالَ: لَا تَغْضَبْ","nar":"","src":"رواه البخاري (6116)","grade":"","occ":"","on":"نعم"},{"n":17,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ","nar":"عن شداد بن أوس رضي الله عنه","src":"رواه مسلم (1955)","grade":"","occ":"","on":"نعم"},{"n":18,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ","nar":"عن أبي ذر ومعاذ بن جبل رضي الله عنهما","src":"رواه الترمذي (1987)","grade":"حسن صحيح","occ":"","on":"نعم"},{"n":19,"cat":"العقيدة والإيمان","head":"عن ابن عباس رضي الله عنهما قال: كنت خلف النبي ﷺ يومًا فقال","text":"يَا غُلَامُ، إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ، وَاعْلَمْ أَنَّ الْأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ، وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ، رُفِعَتِ الْأَقْلَامُ وَجَفَّتِ الصُّحُفُ","nar":"","src":"رواه الترمذي (2516)","grade":"صحيح","occ":"","on":"نعم"},{"n":20,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إِذَا لَمْ تَسْتَحْيِ فَاصْنَعْ مَا شِئْتَ","nar":"عن أبي مسعود البدري رضي الله عنه","src":"رواه البخاري (3483)","grade":"","occ":"","on":"نعم"},{"n":21,"cat":"العقيدة والإيمان","head":"عن سفيان بن عبد الله الثقفي رضي الله عنه قال: قلت: يا رسول الله، قل لي في الإسلام قولًا لا أسأل عنه أحدًا غيرك، قال","text":"قُلْ: آمَنْتُ بِاللَّهِ، ثُمَّ اسْتَقِمْ","nar":"","src":"رواه مسلم (38)","grade":"","occ":"","on":"نعم"},{"n":22,"cat":"العبادات والأركان","head":"عن جابر رضي الله عنه أن رجلًا سأل رسول الله ﷺ فقال","text":"أَرَأَيْتَ إِذَا صَلَّيْتُ الْمَكْتُوبَاتِ، وَصُمْتُ رَمَضَانَ، وَأَحْلَلْتُ الْحَلَالَ، وَحَرَّمْتُ الْحَرَامَ، وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا، أَأَدْخُلُ الْجَنَّةَ؟ قَالَ: نَعَمْ","nar":"","src":"رواه مسلم (15)","grade":"","occ":"","on":"نعم"},{"n":23,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآنِ مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو؛ فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا","nar":"عن أبي مالك الأشعري رضي الله عنه","src":"رواه مسلم (223)","grade":"","occ":"","on":"نعم"},{"n":24,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"يَا عِبَادِي، إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوا، يَا عِبَادِي، كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ فَاسْتَهْدُونِي أَهْدِكُمْ، يَا عِبَادِي، كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ فَاسْتَطْعِمُونِي أُطْعِمْكُمْ، يَا عِبَادِي، كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ فَاسْتَكْسُونِي أَكْسُكُمْ، يَا عِبَادِي، إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ… يَا عِبَادِي، إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ","nar":"عن أبي ذر الغفاري رضي الله عنه","src":"رواه مسلم (2577)","grade":"","occ":"","on":"لا"},{"n":25,"cat":"الذكر والدعاء","head":"عن أبي ذر رضي الله عنه أن ناسًا من أصحاب النبي ﷺ قالوا: يا رسول الله، ذهب أهل الدثور بالأجور؛ يصلون كما نصلي، ويصومون كما نصوم، ويتصدقون بفضول أموالهم، قال","text":"أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ","nar":"","src":"رواه مسلم (1006)","grade":"","occ":"","on":"نعم"},{"n":26,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ: تَعْدِلُ بَيْنَ الِاثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خَطْوَةٍ تَمْشِيهَا إِلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2989) ومسلم (1009)","grade":"","occ":"","on":"نعم"},{"n":27,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ","nar":"عن النواس بن سمعان رضي الله عنه","src":"رواه مسلم (2553)","grade":"","occ":"","on":"نعم"},{"n":28,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ، فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ","nar":"عن العرباض بن سارية رضي الله عنه","src":"رواه أبي داود (4607) والترمذي (2676)","grade":"صحيح","occ":"","on":"نعم"},{"n":29,"cat":"العبادات والأركان","head":"عن معاذ رضي الله عنه قال: قلت: يا رسول الله، أخبرني بعمل يدخلني الجنة ويباعدني عن النار، قال","text":"لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ عَلَيْهِ: تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ… ثُمَّ قَالَ: أَلَا أُخْبِرُكَ بِمَلَاكِ ذَلِكَ كُلِّهِ؟ كُفَّ عَلَيْكَ هَذَا -وَأَشَارَ إِلَى لِسَانِهِ- … وَهَلْ يَكُبُّ النَّاسَ فِي النَّارِ عَلَى وُجُوهِهِمْ إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ","nar":"","src":"رواه الترمذي (2616)","grade":"صحيح","occ":"","on":"نعم"},{"n":30,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا","nar":"عن أبي ثعلبة الخشني رضي الله عنه","src":"رواه الدارقطني (4/184)","grade":"حسن","occ":"","on":"لا"},{"n":31,"cat":"الرقائق والتزكية","head":"عن سهل بن سعد رضي الله عنه أن رجلًا قال: يا رسول الله، دلني على عمل إذا عملته أحبني الله وأحبني الناس، فقال","text":"ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللَّهُ، وَازْهَدْ فِيمَا فِي أَيْدِي النَّاسِ يُحِبُّوكَ","nar":"","src":"رواه ابن ماجه (4102)","grade":"حسن","occ":"","on":"نعم"},{"n":32,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"لَا ضَرَرَ وَلَا ضِرَارَ","nar":"عن أبي سعيد الخدري رضي الله عنه","src":"رواه ابن ماجه (2340) ومالك في الموطأ","grade":"حسن","occ":"","on":"نعم"},{"n":33,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى نَاسٌ دِمَاءَ رِجَالٍ وَأَمْوَالَهُمْ، وَلَكِنَّ الْيَمِينَ عَلَى الْمُدَّعَى عَلَيْهِ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه البخاري (4552) ومسلم (1711)","grade":"","occ":"","on":"نعم"},{"n":34,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ","nar":"عن أبي سعيد الخدري رضي الله عنه","src":"رواه مسلم (49)","grade":"","occ":"","on":"نعم"},{"n":35,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا، الْمُسْلِمُ أَخُو الْمُسْلِمِ: لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا -وَيُشِيرُ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ- بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ، وَمَالُهُ، وَعِرْضُهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2564)","grade":"","occ":"","on":"نعم"},{"n":36,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2699)","grade":"","occ":"","on":"نعم"},{"n":37,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذَلِكَ؛ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، فَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً","nar":"عن ابن عباس رضي الله عنهما","src":"رواه البخاري (6491) ومسلم (131)","grade":"","occ":"","on":"نعم"},{"n":38,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنِ اسْتَعَاذَنِي لَأُعِيذَنَّهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6502)","grade":"","occ":"","on":"نعم"},{"n":39,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه ابن ماجه (2045)","grade":"صحيح","occ":"","on":"نعم"},{"n":40,"cat":"الرقائق والتزكية","head":"عن ابن عمر رضي الله عنهما قال: أخذ رسول الله ﷺ بمنكبي فقال","text":"كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ","nar":"","src":"رواه البخاري (6416)","grade":"","occ":"","on":"نعم"},{"n":41,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه نصر المقدسي في الحجة (وذكره النووي في الأربعين: 41)","grade":"","occ":"","on":"لا"},{"n":42,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"يَا ابْنَ آدَمَ، إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ عَلَى مَا كَانَ فِيكَ وَلَا أُبَالِي، يَا ابْنَ آدَمَ، لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ وَلَا أُبَالِي، يَا ابْنَ آدَمَ، إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الْأَرْضِ خَطَايَا ثُمَّ لَقِيتَنِي لَا تُشْرِكُ بِي شَيْئًا لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه الترمذي (3540)","grade":"حسن صحيح","occ":"last_third","on":"نعم"},{"n":43,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6406) ومسلم (2694)","grade":"","occ":"morning,evening","on":"نعم"},{"n":44,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه البخاري (5027)","grade":"","occ":"ramadan","on":"نعم"},{"n":45,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ","nar":"عن عائشة رضي الله عنها","src":"رواه البخاري (4937) ومسلم (798)","grade":"","occ":"ramadan","on":"نعم"},{"n":46,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ","nar":"عن أبي أمامة الباهلي رضي الله عنه","src":"رواه مسلم (804)","grade":"","occ":"ramadan","on":"نعم"},{"n":47,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ","nar":"عن أبي موسى الأشعري رضي الله عنه","src":"رواه البخاري (6407)","grade":"","occ":"","on":"نعم"},{"n":48,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2564)","grade":"","occ":"","on":"نعم"},{"n":49,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2699)","grade":"","occ":"","on":"نعم"},{"n":50,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (1631)","grade":"","occ":"","on":"نعم"},{"n":51,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي","nar":"عن مالك بن الحويرث رضي الله عنه","src":"رواه البخاري (631)","grade":"","occ":"","on":"نعم"},{"n":52,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (482)","grade":"","occ":"last_third","on":"نعم"},{"n":53,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ؟ قَالُوا: لَا يَبْقَى مِنْ دَرَنِهِ شَيْءٌ، قَالَ: فَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهِنَّ الْخَطَايَا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (528) ومسلم (667)","grade":"","occ":"","on":"نعم"},{"n":54,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكُ الصَّلَاةِ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه مسلم (82)","grade":"","occ":"","on":"نعم"},{"n":55,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً","nar":"عن ابن عمر رضي الله عنهما","src":"رواه البخاري (645) ومسلم (650)","grade":"","occ":"","on":"نعم"},{"n":56,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه مسلم (384)","grade":"","occ":"friday,mawlid","on":"نعم"},{"n":57,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"الدُّعَاءُ هُوَ الْعِبَادَةُ","nar":"عن النعمان بن بشير رضي الله عنهما","src":"رواه أبي داود (1479) والترمذي (2969)","grade":"صحيح","occ":"friday_hour","on":"نعم"},{"n":58,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6340) ومسلم (2735)","grade":"","occ":"friday_hour","on":"نعم"},{"n":59,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضٍ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً فَاضْطَجَعَ فِي ظِلِّهَا قَدْ أَيِسَ مِنْ رَاحِلَتِهِ، فَبَيْنَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا قَائِمَةً عِنْدَهُ، فَأَخَذَ بِخِطَامِهَا ثُمَّ قَالَ مِنْ شِدَّةِ الْفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الْفَرَحِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (6309) ومسلم (2747)","grade":"","occ":"last_third","on":"نعم"},{"n":60,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"التَّائِبُ مِنَ الذَّنْبِ كَمَنْ لَا ذَنْبَ لَهُ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه ابن ماجه (4250)","grade":"حسن","occ":"last_third","on":"نعم"},{"n":61,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا، وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا","nar":"عن ابن مسعود رضي الله عنه","src":"رواه البخاري (6094) ومسلم (2607)","grade":"","occ":"","on":"نعم"},{"n":62,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (33) ومسلم (59)","grade":"","occ":"","on":"نعم"},{"n":63,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6114) ومسلم (2609)","grade":"","occ":"","on":"نعم"},{"n":64,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2588)","grade":"","occ":"","on":"نعم"},{"n":65,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ، ارْحَمُوا مَنْ فِي الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه أبي داود (4941) والترمذي (1924)","grade":"صحيح","occ":"","on":"نعم"},{"n":66,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ. قَالَ رَجُلٌ: إِنَّ الرَّجُلَ يُحِبُّ أَنْ يَكُونَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً، قَالَ: إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ، الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه مسلم (91)","grade":"","occ":"","on":"نعم"},{"n":67,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ أَحَاسِنَكُمْ أَخْلَاقًا","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه الترمذي (2018)","grade":"حسن","occ":"","on":"نعم"},{"n":68,"cat":"الأسرة وصلة الرحم","head":"عن أبي هريرة رضي الله عنه قال: جاء رجل إلى رسول الله ﷺ فقال: يا رسول الله، من أحق الناس بحسن صحابتي؟ قال","text":"أُمُّكَ. قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ. قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أُمُّكَ. قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أَبُوكَ","nar":"","src":"رواه البخاري (5971) ومسلم (2548)","grade":"","occ":"","on":"نعم"},{"n":69,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (5986) ومسلم (2557)","grade":"","occ":"","on":"نعم"},{"n":70,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنِ الْوَاصِلُ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه البخاري (5991)","grade":"","occ":"","on":"نعم"},{"n":71,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ: الْإِمَامُ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ فِي أَهْلِهِ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَمَسْئُولَةٌ عَنْ رَعِيَّتِهَا، وَالْخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، وَكُلُّكُمْ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ","nar":"عن ابن عمر رضي الله عنهما","src":"رواه البخاري (893) ومسلم (1829)","grade":"","occ":"","on":"نعم"},{"n":72,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي","nar":"عن عائشة رضي الله عنها","src":"رواه الترمذي (3895) وابن ماجه (1977)","grade":"صحيح","occ":"","on":"نعم"},{"n":73,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (3331) ومسلم (1468)","grade":"","occ":"","on":"نعم"},{"n":74,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"رَحِمَ اللَّهُ رَجُلًا سَمْحًا إِذَا بَاعَ، وَإِذَا اشْتَرَى، وَإِذَا اقْتَضَى","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه البخاري (2076)","grade":"","occ":"","on":"نعم"},{"n":75,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَنْ غَشَّنَا فَلَيْسَ مِنَّا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (101)","grade":"","occ":"","on":"نعم"},{"n":76,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"أَعْطُوا الْأَجِيرَ أَجْرَهُ قَبْلَ أَنْ يَجِفَّ عَرَقُهُ","nar":"عن عبد الله بن عمر رضي الله عنهما","src":"رواه ابن ماجه (2443)","grade":"صحيح","occ":"","on":"نعم"},{"n":77,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، فَمَنْ لَمْ يَجِدْ فَبِكَلِمَةٍ طَيِّبَةٍ","nar":"عن عدي بن حاتم رضي الله عنه","src":"رواه البخاري (6540) ومسلم (1016)","grade":"","occ":"","on":"نعم"},{"n":78,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"السَّاعِي عَلَى الْأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ، أَوِ الْقَائِمِ اللَّيْلَ الصَّائِمِ النَّهَارَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (5353) ومسلم (2982)","grade":"","occ":"","on":"نعم"},{"n":79,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا. وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى، وَفَرَّجَ بَيْنَهُمَا شَيْئًا","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه البخاري (5304)","grade":"","occ":"","on":"نعم"},{"n":80,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه أبي داود (4811) والترمذي (1954)","grade":"صحيح","occ":"","on":"نعم"},{"n":81,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"عَجَبًا لِأَمْرِ الْمُؤْمِنِ، إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ","nar":"عن صهيب الرومي رضي الله عنه","src":"رواه مسلم (2999)","grade":"","occ":"","on":"نعم"},{"n":82,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ، وَلَا وَصَبٍ، وَلَا هَمٍّ، وَلَا حُزْنٍ، وَلَا أَذًى، وَلَا غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ","nar":"عن أبي سعيد وأبي هريرة رضي الله عنهما","src":"رواه البخاري (5641) ومسلم (2573)","grade":"","occ":"","on":"نعم"},{"n":83,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ، وَفِي كُلٍّ خَيْرٌ، احْرِصْ عَلَى مَا يَنْفَعُكَ، وَاسْتَعِنْ بِاللَّهِ وَلَا تَعْجَزْ، وَإِنْ أَصَابَكَ شَيْءٌ فَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ كَانَ كَذَا وَكَذَا، وَلَكِنْ قُلْ: قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ، فَإِنَّ (لَوْ) تَفْتَحُ عَمَلَ الشَّيْطَانِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2664)","grade":"","occ":"","on":"نعم"},{"n":84,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"انْظُرُوا إِلَى مَنْ أَسْفَلَ مِنْكُمْ، وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ، فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2963)","grade":"","occ":"","on":"نعم"},{"n":85,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ، وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6446) ومسلم (1051)","grade":"","occ":"","on":"نعم"},{"n":86,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ وَالْفَرَاغُ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه البخاري (6412)","grade":"","occ":"","on":"نعم"},{"n":87,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"اغْتَنِمْ خَمْسًا قَبْلَ خَمْسٍ: شَبَابَكَ قَبْلَ هَرَمِكَ، وَصِحَّتَكَ قَبْلَ سَقَمِكَ، وَغِنَاكَ قَبْلَ فَقْرِكَ، وَفَرَاغَكَ قَبْلَ شُغُلِكَ، وَحَيَاتَكَ قَبْلَ مَوْتِكَ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه الحاكم في المستدرك (7846) والبيهقي في شعب الإيمان","grade":"صحيح","occ":"","on":"نعم"},{"n":88,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"أَتَدْرُونَ مَا الْغِيبَةُ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ. قِيلَ: أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ؟ قَالَ: إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ، وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ بَهَتَّهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2589)","grade":"","occ":"","on":"نعم"},{"n":89,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَا يَدْخُلُ الْجَنَّةَ قَتَّاتٌ","nar":"عن حذيفة بن اليمان رضي الله عنه","src":"رواه البخاري (6056) ومسلم (105)","grade":"","occ":"","on":"نعم"},{"n":90,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"مَنْ كَانَ لَهُ ثَلَاثُ بَنَاتٍ فَصَبَرَ عَلَيْهِنَّ، وَأَطْعَمَهُنَّ، وَسَقَاهُنَّ، وَكَسَاهُنَّ مِنْ جِدَتِهِ، كُنَّ لَهُ حِجَابًا مِنَ النَّارِ يَوْمَ الْقِيَامَةِ","nar":"عن عقبة بن عامر رضي الله عنه","src":"رواه ابن ماجه (3669) وأحمد","grade":"صحيح","occ":"","on":"نعم"},{"n":91,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"يَسِّرُوا وَلَا تُعَسِّرُوا، وَبَشِّرُوا وَلَا تُنَفِّرُوا","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (69) ومسلم (1734)","grade":"","occ":"","on":"نعم"},{"n":92,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ","nar":"عن عائشة رضي الله عنها","src":"رواه مسلم (2594)","grade":"","occ":"","on":"نعم"},{"n":93,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه البخاري (10) ومسلم (40)","grade":"","occ":"","on":"نعم"},{"n":94,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ؛ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى","nar":"عن النعمان بن بشير رضي الله عنهما","src":"رواه البخاري (6011) ومسلم (2586)","grade":"","occ":"","on":"نعم"},{"n":95,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (38) ومسلم (760)","grade":"","occ":"ramadan_start,ramadan","on":"نعم"},{"n":96,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1901) ومسلم (760)","grade":"","occ":"last_ten","on":"نعم"},{"n":97,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللَّهِ مِنْ هَذِهِ الْأَيَّامِ -يَعْنِي أَيَّامَ الْعَشْرِ- قَالُوا: يَا رَسُولَ اللَّهِ، وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ؟ قَالَ: وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ، إِلَّا رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَيْءٍ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه أبي داود (2438) والترمذي (757) (صحيح)، ونحوه في البخاري (969)","grade":"","occ":"dhulhijja_ten","on":"نعم"},{"n":98,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ","nar":"عن معاوية بن أبي سفيان رضي الله عنه","src":"رواه البخاري (71) ومسلم (1037)","grade":"","occ":"","on":"نعم"},{"n":99,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ","nar":"عن أبي مسعود الأنصاري رضي الله عنه","src":"رواه مسلم (1893)","grade":"","occ":"","on":"نعم"},{"n":100,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"الْمَرْءُ مَعَ مَنْ أَحَبَّ","nar":"عن أنس بن مالك وعبد الله بن مسعود رضي الله عنهما","src":"رواه البخاري (6168) ومسلم (2640)","grade":"","occ":"","on":"نعم"},{"n":101,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ: أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ، وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (16) ومسلم (43)","grade":"","occ":"","on":"نعم"},{"n":102,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، فِي يَوْمٍ مِائَةَ مَرَّةٍ، كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (3293) ومسلم (2691)","grade":"","occ":"morning","on":"لا"},{"n":103,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ بَاعًا، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (7405) ومسلم (2675)","grade":"","occ":"evening","on":"نعم"},{"n":104,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ","text":"مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ، وَمَنْ يُرَائِي يُرَائِي اللَّهُ بِهِ","nar":"عن جندب بن عبد الله رضي الله عنه","src":"رواه البخاري (6499) ومسلم (2987)","grade":"","occ":"","on":"نعم"},{"n":105,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ","nar":"عن عائشة رضي الله عنها","src":"رواه البخاري (6464) ومسلم (783)","grade":"","occ":"","on":"نعم"},{"n":106,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"الصَّلَوَاتُ الْخَمْسُ، وَالْجُمُعَةُ إِلَى الْجُمُعَةِ، وَرَمَضَانُ إِلَى رَمَضَانَ، مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتَنَبَ الْكَبَائِرَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (233)","grade":"","occ":"friday","on":"نعم"},{"n":107,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ، حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه مسلم (245)","grade":"","occ":"","on":"نعم"},{"n":108,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"الْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا، وَالْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1773) ومسلم (1349)","grade":"","occ":"dhulhijja_ten,arafah","on":"نعم"},{"n":109,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"صِيَامُ يَوْمِ عَرَفَةَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ، وَصِيَامُ يَوْمِ عَاشُورَاءَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ","nar":"عن أبي قتادة الأنصاري رضي الله عنه","src":"رواه مسلم (1162)","grade":"","occ":"arafah,ashura","on":"نعم"},{"n":110,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (1923) ومسلم (1095)","grade":"","occ":"suhur","on":"نعم"},{"n":111,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"سَيِّدُ الِاسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. مَنْ قَالَهَا مِنَ النَّهَارِ مُوقِنًا بِهَا فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ فَهُوَ مِنْ أَهْلِ الْجَنَّةِ","nar":"عن شداد بن أوس رضي الله عنه","src":"رواه البخاري (6306)","grade":"","occ":"morning,last_third","on":"لا"},{"n":112,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"دَعْوَةُ الْمَرْءِ الْمُسْلِمِ لِأَخِيهِ بِظَهْرِ الْغَيْبِ مُسْتَجَابَةٌ، عِنْدَ رَأْسِهِ مَلَكٌ مُوَكَّلٌ، كُلَّمَا دَعَا لِأَخِيهِ بِخَيْرٍ قَالَ الْمَلَكُ الْمُوَكَّلُ بِهِ: آمِينَ، وَلَكَ بِمِثْلٍ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه مسلم (2733)","grade":"","occ":"","on":"نعم"},{"n":113,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لَا شَكَّ فِيهِنَّ: دَعْوَةُ الْمَظْلُومِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه أبي داود (1536) والترمذي (1905)","grade":"حسن","occ":"friday_hour","on":"نعم"},{"n":114,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لَا أَقُولُ (الم) حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ، وَلَامٌ حَرْفٌ، وَمِيمٌ حَرْفٌ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه الترمذي (2910)","grade":"صحيح","occ":"ramadan","on":"نعم"},{"n":115,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"إِنَّ الْعُلَمَاءَ وَرَثَةُ الْأَنْبِيَاءِ، إِنَّ الْأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلَا دِرْهَمًا، إِنَّمَا وَرَّثُوا الْعِلْمَ، فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه أبي داود (3641) والترمذي (2682)","grade":"صحيح","occ":"","on":"نعم"},{"n":116,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"بَلِّغُوا عَنِّي وَلَوْ آيَةً","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه البخاري (3461)","grade":"","occ":"","on":"نعم"},{"n":117,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ","nar":"عن أبي ذر الغفاري رضي الله عنه","src":"رواه مسلم (2626)","grade":"","occ":"","on":"نعم"},{"n":118,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2989) ومسلم (1009)","grade":"","occ":"","on":"نعم"},{"n":119,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلَا تَحَسَّسُوا، وَلَا تَجَسَّسُوا، وَلَا تَنَافَسُوا، وَلَا تَحَاسَدُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6064) ومسلم (2563)","grade":"","occ":"","on":"نعم"},{"n":120,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَا كَانَ الْفُحْشُ فِي شَيْءٍ إِلَّا شَانَهُ، وَمَا كَانَ الْحَيَاءُ فِي شَيْءٍ إِلَّا زَانَهُ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه الترمذي (1974) وابن ماجه (4185)","grade":"صحيح","occ":"","on":"نعم"},{"n":121,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ، وَلَا اللَّعَّانِ، وَلَا الْفَاحِشِ، وَلَا الْبَذِيءِ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه الترمذي (1977)","grade":"صحيح","occ":"","on":"نعم"},{"n":122,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَنْ كَظَمَ غَيْظًا وَهُوَ قَادِرٌ عَلَى أَنْ يُنْفِذَهُ دَعَاهُ اللَّهُ عَزَّ وَجَلَّ عَلَى رُءُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ حَتَّى يُخَيِّرَهُ مِنَ الْحُورِ الْعِينِ مَا شَاءَ","nar":"عن معاذ بن أنس رضي الله عنه","src":"رواه أبي داود (4777) والترمذي (2021)","grade":"حسن","occ":"","on":"نعم"},{"n":123,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"رِضَا الرَّبِّ فِي رِضَا الْوَالِدِ، وَسَخَطُ الرَّبِّ فِي سَخَطِ الْوَالِدِ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه الترمذي (1899)","grade":"صحيح","occ":"","on":"نعم"},{"n":124,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"لَا يَدْخُلُ الْجَنَّةَ قَاطِعٌ","nar":"عن جبير بن مطعم رضي الله عنه","src":"رواه البخاري (5984) ومسلم (2556)","grade":"","occ":"","on":"نعم"},{"n":125,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"لَا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً، إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (1469)","grade":"","occ":"","on":"نعم"},{"n":126,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"مَا نَحَلَ وَالِدٌ وَلَدًا مِنْ نَحْلٍ أَفْضَلَ مِنْ أَدَبٍ حَسَنٍ","nar":"عن سعيد بن العاص رضي الله عنه","src":"رواه الترمذي (1952)","grade":"حسن","occ":"","on":"لا"},{"n":127,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا، فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَذَبَا وَكَتَمَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا","nar":"عن حكيم بن حزام رضي الله عنه","src":"رواه البخاري (2079) ومسلم (1532)","grade":"","occ":"","on":"نعم"},{"n":128,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَطْلُ الْغَنِيِّ ظُلْمٌ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2287) ومسلم (1564)","grade":"","occ":"","on":"نعم"},{"n":129,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَنْ أَخَذَ أَمْوَالَ النَّاسِ يُرِيدُ أَدَاءَهَا أَدَّى اللَّهُ عَنْهُ، وَمَنْ أَخَذَ يُرِيدُ إِتْلَافَهَا أَتْلَفَهُ اللَّهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2387)","grade":"","occ":"","on":"نعم"},{"n":130,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ يُحِبُّ إِذَا عَمِلَ أَحَدُكُمْ عَمَلًا أَنْ يُتْقِنَهُ","nar":"عن عائشة رضي الله عنها","src":"رواه أبو يعلى (4386) والبيهقي في شعب الإيمان","grade":"حسن","occ":"","on":"نعم"},{"n":131,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ عَلَيْهِ السَّلَامُ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ","nar":"عن المقدام بن معديكرب رضي الله عنه","src":"رواه البخاري (2072)","grade":"","occ":"","on":"نعم"},{"n":132,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"كُلُّ مُسْكِرٍ خَمْرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ","nar":"عن ابن عمر رضي الله عنهما","src":"رواه مسلم (2003)","grade":"","occ":"","on":"نعم"},{"n":133,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه مسلم (2578)","grade":"","occ":"","on":"نعم"},{"n":134,"cat":"الحلال والحرام والورع","head":"عن جابر رضي الله عنه قال","text":"لَعَنَ رَسُولُ اللَّهِ ﷺ آكِلَ الرِّبَا، وَمُؤْكِلَهُ، وَكَاتِبَهُ، وَشَاهِدَيْهِ، وَقَالَ: هُمْ سَوَاءٌ","nar":"","src":"رواه مسلم (1598)","grade":"","occ":"","on":"نعم"},{"n":135,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا. وَشَبَّكَ بَيْنَ أَصَابِعِهِ","nar":"عن أبي موسى الأشعري رضي الله عنه","src":"رواه البخاري (481) ومسلم (2585)","grade":"","occ":"","on":"نعم"},{"n":136,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ: رَدُّ السَّلَامِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ، وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1240) ومسلم (2162)","grade":"","occ":"","on":"نعم"},{"n":137,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ","nar":"عن عائشة وابن عمر رضي الله عنهم","src":"رواه البخاري (6014) ومسلم (2625)","grade":"","occ":"","on":"نعم"},{"n":138,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"وَاللَّهِ لَا يُؤْمِنُ، وَاللَّهِ لَا يُؤْمِنُ، وَاللَّهِ لَا يُؤْمِنُ. قِيلَ: وَمَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: الَّذِي لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ","nar":"عن أبي شريح الخزاعي رضي الله عنه","src":"رواه البخاري (6016)","grade":"","occ":"","on":"نعم"},{"n":139,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه الطبراني في الأوسط (5787)","grade":"حسن","occ":"","on":"نعم"},{"n":140,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"أَحَبُّ النَّاسِ إِلَى اللَّهِ أَنْفَعُهُمْ لِلنَّاسِ، وَأَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ سُرُورٌ تُدْخِلُهُ عَلَى مُسْلِمٍ، أَوْ تَكْشِفُ عَنْهُ كُرْبَةً، أَوْ تَقْضِي عَنْهُ دَيْنًا، أَوْ تَطْرُدُ عَنْهُ جُوعًا، وَلَأَنْ أَمْشِيَ مَعَ أَخٍ لِي فِي حَاجَةٍ أَحَبُّ إِلَيَّ مِنْ أَنْ أَعْتَكِفَ فِي هَذَا الْمَسْجِدِ شَهْرًا","nar":"عن ابن عمر رضي الله عنهما","src":"رواه الطبراني في الكبير (13646)","grade":"حسن","occ":"","on":"نعم"},{"n":141,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَ فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَ أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ","nar":"عن أبي برزة الأسلمي رضي الله عنه","src":"رواه الترمذي (2417)","grade":"صحيح","occ":"","on":"نعم"},{"n":142,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"أَكْثِرُوا ذِكْرَ هَاذِمِ اللَّذَّاتِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه الترمذي (2307) والنسائي (1824)","grade":"حسن صحيح","occ":"","on":"نعم"},{"n":143,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ، وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه مسلم (2822)","grade":"","occ":"","on":"نعم"},{"n":144,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"اتَّقِ دَعْوَةَ الْمَظْلُومِ، فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه البخاري (2448) ومسلم (19)","grade":"","occ":"","on":"نعم"},{"n":145,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ، مُعَافًى فِي جَسَدِهِ، عِنْدَهُ قُوتُ يَوْمِهِ، فَكَأَنَّمَا حِيزَتْ لَهُ الدُّنْيَا","nar":"عن عبيد الله بن محصن رضي الله عنه","src":"رواه الترمذي (2346) وابن ماجه (4141)","grade":"حسن","occ":"","on":"نعم"},{"n":146,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِيَّاكُمْ وَمُحَقَّرَاتِ الذُّنُوبِ، فَإِنَّهُنَّ يَجْتَمِعْنَ عَلَى الرَّجُلِ حَتَّى يُهْلِكْنَهُ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه أحمد (3808)","grade":"صحيح","occ":"","on":"نعم"},{"n":147,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"كُلُّ بَنِي آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه الترمذي (2499) وابن ماجه (4251)","grade":"حسن","occ":"last_third","on":"نعم"},{"n":148,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"الْكَيِّسُ مَنْ دَانَ نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ الْمَوْتِ، وَالْعَاجِزُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا وَتَمَنَّى عَلَى اللَّهِ","nar":"عن شداد بن أوس رضي الله عنه","src":"رواه الترمذي (2459)","grade":"حسن","occ":"","on":"لا"},{"n":149,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"تَرَكْتُ فِيكُمْ أَمْرَيْنِ لَنْ تَضِلُّوا مَا تَمَسَّكْتُمْ بِهِمَا: كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّهِ","nar":"عن مالك بلاغاً، وله شواهد صحيحة","src":"رواه مالك في الموطأ (1594)","grade":"","occ":"","on":"نعم"},{"n":150,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"مَنْ كَانَ آخِرُ كَلَامِهِ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ","nar":"عن معاذ بن جبل رضي الله عنه","src":"رواه أبي داود (3116)","grade":"صحيح","occ":"","on":"نعم"},{"n":151,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"الْإِيمَانُ بِضْعٌ وَسَبْعُونَ شُعْبَةً، فَأَفْضَلُهَا قَوْلُ: لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (35)","grade":"","occ":"","on":"نعم"},{"n":152,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (15) ومسلم (44)","grade":"","occ":"mawlid","on":"نعم"},{"n":153,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"ذَاقَ طَعْمَ الْإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ رَسُولًا","nar":"عن العباس بن عبد المطلب رضي الله عنه","src":"رواه مسلم (34)","grade":"","occ":"","on":"نعم"},{"n":154,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه مسلم (26)","grade":"","occ":"","on":"نعم"},{"n":155,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا، مِائَةً إِلَّا وَاحِدًا، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2736) ومسلم (2677)","grade":"","occ":"","on":"نعم"},{"n":156,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلًا أَشْرَكَ فِيهِ مَعِي غَيْرِي تَرَكْتُهُ وَشِرْكَهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2985)","grade":"","occ":"","on":"نعم"},{"n":157,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، يَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ؟ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ؟","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1145) ومسلم (758)","grade":"","occ":"last_third","on":"نعم"},{"n":158,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (54)","grade":"","occ":"","on":"نعم"},{"n":159,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (3194) ومسلم (2751)","grade":"","occ":"","on":"نعم"},{"n":160,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ","text":"جَعَلَ اللَّهُ الرَّحْمَةَ مِائَةَ جُزْءٍ، فَأَمْسَكَ عِنْدَهُ تِسْعَةً وَتِسْعِينَ جُزْءًا، وَأَنْزَلَ فِي الْأَرْضِ جُزْءًا وَاحِدًا، فَمِنْ ذَلِكَ الْجُزْءِ يَتَرَاحَمُ الْخَلْقُ، حَتَّى تَرْفَعَ الْفَرَسُ حَافِرَهَا عَنْ وَلَدِهَا خَشْيَةَ أَنْ تُصِيبَهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6000) ومسلم (2752)","grade":"","occ":"","on":"نعم"},{"n":161,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"لَنْ يُدْخِلَ أَحَدًا عَمَلُهُ الْجَنَّةَ. قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِي اللَّهُ بِفَضْلٍ وَرَحْمَةٍ، فَسَدِّدُوا وَقَارِبُوا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (5673) ومسلم (2816)","grade":"","occ":"","on":"نعم"},{"n":162,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه البخاري (6488)","grade":"","occ":"","on":"نعم"},{"n":163,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"أَعْدَدْتُ لِعِبَادِيَ الصَّالِحِينَ مَا لَا عَيْنٌ رَأَتْ، وَلَا أُذُنٌ سَمِعَتْ، وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (3244) ومسلم (2824)","grade":"","occ":"","on":"نعم"},{"n":164,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ","nar":"عن عبادة بن الصامت رضي الله عنه","src":"رواه البخاري (6507) ومسلم (2683)","grade":"","occ":"","on":"نعم"},{"n":165,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: الْإِمَامُ الْعَادِلُ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ رَبِّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ طَلَبَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ أَخْفَى حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (660) ومسلم (1031)","grade":"","occ":"","on":"لا"},{"n":166,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي؟ الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2566)","grade":"","occ":"","on":"نعم"},{"n":167,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"كَذَّبَنِي ابْنُ آدَمَ وَلَمْ يَكُنْ لَهُ ذَلِكَ، وَشَتَمَنِي وَلَمْ يَكُنْ لَهُ ذَلِكَ، فَأَمَّا تَكْذِيبُهُ إِيَّايَ فَزَعَمَ أَنِّي لَا أَقْدِرُ أَنْ أُعِيدَهُ كَمَا كَانَ، وَأَمَّا شَتْمُهُ إِيَّايَ فَقَوْلُهُ: لِي وَلَدٌ، فَسُبْحَانِي أَنْ أَتَّخِذَ صَاحِبَةً أَوْ وَلَدًا","nar":"عن ابن عباس رضي الله عنهما","src":"رواه البخاري (4482)","grade":"","occ":"","on":"نعم"},{"n":168,"cat":"العقيدة والإيمان","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"يُؤْذِينِي ابْنُ آدَمَ؛ يَسُبُّ الدَّهْرَ وَأَنَا الدَّهْرُ، بِيَدِيَ الْأَمْرُ أُقَلِّبُ اللَّيْلَ وَالنَّهَارَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (4826) ومسلم (2246)","grade":"","occ":"","on":"نعم"},{"n":169,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَنْ يَأْبَى؟ قَالَ: مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (7280)","grade":"","occ":"","on":"نعم"},{"n":170,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"لَا تُطْرُونِي كَمَا أَطْرَتِ النَّصَارَى ابْنَ مَرْيَمَ، فَإِنَّمَا أَنَا عَبْدُهُ، فَقُولُوا: عَبْدُ اللَّهِ وَرَسُولُهُ","nar":"عن عمر بن الخطاب رضي الله عنه","src":"رواه البخاري (3445)","grade":"","occ":"","on":"نعم"},{"n":171,"cat":"العقيدة والمنهج","head":"قال رسول الله ﷺ","text":"إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (39)","grade":"","occ":"","on":"نعم"},{"n":172,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ","nar":"عن بريدة رضي الله عنه","src":"رواه الترمذي (2621) والنسائي (463)","grade":"صحيح","occ":"","on":"نعم"},{"n":173,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ","nar":"عن أبي موسى الأشعري رضي الله عنه","src":"رواه البخاري (574) ومسلم (635)","grade":"","occ":"","on":"نعم"},{"n":174,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَكَأَنَّمَا قَامَ نِصْفَ اللَّيْلِ، وَمَنْ صَلَّى الصُّبْحَ فِي جَمَاعَةٍ فَكَأَنَّمَا صَلَّى اللَّيْلَ كُلَّهُ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه مسلم (656)","grade":"","occ":"","on":"نعم"},{"n":175,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَا مِنْ عَبْدٍ مُسْلِمٍ يُصَلِّي لِلَّهِ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً تَطَوُّعًا غَيْرَ فَرِيضَةٍ إِلَّا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ","nar":"عن أم حبيبة رضي الله عنها","src":"رواه مسلم (728)","grade":"","occ":"","on":"نعم"},{"n":176,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا","nar":"عن عائشة رضي الله عنها","src":"رواه مسلم (725)","grade":"","occ":"morning","on":"نعم"},{"n":177,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ، وَأَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (1163)","grade":"","occ":"muharram","on":"نعم"},{"n":178,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ فِي الْجَنَّةِ مِثْلَهُ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه البخاري (450) ومسلم (533)","grade":"","occ":"","on":"نعم"},{"n":179,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ غَدَا إِلَى الْمَسْجِدِ أَوْ رَاحَ أَعَدَّ اللَّهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ كُلَّمَا غَدَا أَوْ رَاحَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (662) ومسلم (669)","grade":"","occ":"","on":"نعم"},{"n":180,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ، ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ يَسْتَهِمُوا عَلَيْهِ لَاسْتَهَمُوا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (615) ومسلم (437)","grade":"","occ":"","on":"نعم"},{"n":181,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه البخاري (614)","grade":"","occ":"","on":"نعم"},{"n":182,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه أبو داود (521) والترمذي (212)","grade":"صحيح","occ":"","on":"نعم"},{"n":183,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"الصِّيَامُ جُنَّةٌ، فَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا يَرْفُثْ وَلَا يَصْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ: إِنِّي امْرُؤٌ صَائِمٌ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1904) ومسلم (1151)","grade":"","occ":"ramadan","on":"نعم"},{"n":184,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1903)","grade":"","occ":"ramadan","on":"نعم"},{"n":185,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"إِنَّ فِي الْجَنَّةِ بَابًا يُقَالُ لَهُ الرَّيَّانُ، يَدْخُلُ مِنْهُ الصَّائِمُونَ يَوْمَ الْقِيَامَةِ، لَا يَدْخُلُ مِنْهُ أَحَدٌ غَيْرُهُمْ","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه البخاري (1896) ومسلم (1152)","grade":"","occ":"ramadan","on":"نعم"},{"n":186,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِ، غَيْرَ أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْئًا","nar":"عن زيد بن خالد الجهني رضي الله عنه","src":"رواه الترمذي (807) وابن ماجه (1746)","grade":"صحيح","occ":"iftar","on":"نعم"},{"n":187,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"إِذَا جَاءَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ، وَغُلِّقَتْ أَبْوَابُ النَّارِ، وَصُفِّدَتِ الشَّيَاطِينُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1899) ومسلم (1079)","grade":"","occ":"ramadan_start","on":"نعم"},{"n":188,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (37) ومسلم (759)","grade":"","occ":"ramadan","on":"نعم"},{"n":189,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"لِلصَّائِمِ فَرْحَتَانِ: فَرْحَةٌ عِنْدَ فِطْرِهِ، وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (7492) ومسلم (1151)","grade":"","occ":"iftar","on":"نعم"},{"n":190,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه البخاري (1957) ومسلم (1098)","grade":"","occ":"iftar","on":"نعم"},{"n":191,"cat":"العبادات والأركان","head":"عن ابن عمر رضي الله عنهما قال: كان رسول الله ﷺ إذا أفطر قال","text":"ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","nar":"","src":"رواه أبو داود (2357)","grade":"حسن","occ":"iftar","on":"نعم"},{"n":192,"cat":"العبادات والأركان","head":"عن عائشة رضي الله عنها قالت","text":"كَانَ رَسُولُ اللَّهِ ﷺ إِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَهُ، وَأَحْيَا لَيْلَهُ، وَأَيْقَظَ أَهْلَهُ","nar":"","src":"رواه البخاري (2024) ومسلم (1174)","grade":"","occ":"last_ten","on":"نعم"},{"n":193,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْوِتْرِ مِنَ الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ","nar":"عن عائشة رضي الله عنها","src":"رواه البخاري (2017)","grade":"","occ":"last_ten","on":"نعم"},{"n":194,"cat":"الذكر والدعاء","head":"عن عائشة رضي الله عنها قالت: قلت: يا رسول الله، أرأيت إن علمت أي ليلة ليلة القدر، ما أقول فيها؟ قال","text":"قُولِي: اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","nar":"","src":"رواه الترمذي (3513) وابن ماجه (3850)","grade":"صحيح","occ":"last_ten","on":"نعم"},{"n":195,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ","nar":"عن أبي أيوب الأنصاري رضي الله عنه","src":"رواه مسلم (1164)","grade":"","occ":"shawwal_six","on":"نعم"},{"n":196,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"زَكَاةُ الْفِطْرِ طُهْرَةٌ لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ، وَطُعْمَةٌ لِلْمَسَاكِينِ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه أبو داود (1609) وابن ماجه (1827)","grade":"حسن","occ":"zakat_fitr","on":"نعم"},{"n":197,"cat":"العبادات والأركان","head":"عن أبي قتادة رضي الله عنه أن رسول الله ﷺ سُئل عن صوم يوم الاثنين فقال","text":"ذَاكَ يَوْمٌ وُلِدْتُ فِيهِ، وَيَوْمٌ بُعِثْتُ -أَوْ أُنْزِلَ عَلَيَّ- فِيهِ","nar":"","src":"رواه مسلم (1162)","grade":"","occ":"mon_thu,mawlid","on":"نعم"},{"n":198,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"تُعْرَضُ الْأَعْمَالُ يَوْمَ الِاثْنَيْنِ وَالْخَمِيسِ، فَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه الترمذي (747)","grade":"صحيح","occ":"mon_thu","on":"نعم"},{"n":199,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"ذَلِكَ شَهْرٌ يَغْفُلُ النَّاسُ عَنْهُ بَيْنَ رَجَبٍ وَرَمَضَانَ، وَهُوَ شَهْرٌ تُرْفَعُ فِيهِ الْأَعْمَالُ إِلَى رَبِّ الْعَالَمِينَ، فَأُحِبُّ أَنْ يُرْفَعَ عَمَلِي وَأَنَا صَائِمٌ","nar":"عن أسامة بن زيد رضي الله عنهما","src":"رواه النسائي (2357)","grade":"حسن","occ":"shaban","on":"نعم"},{"n":200,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَحَبُّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ، كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ، كَانَ يَنَامُ نِصْفَ اللَّيْلِ وَيَقُومُ ثُلُثَهُ وَيَنَامُ سُدُسَهُ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه البخاري (1131) ومسلم (1159)","grade":"","occ":"dawud","on":"نعم"},{"n":201,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبِيُّونَ مِنْ قَبْلِي: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه الترمذي (3585)","grade":"حسن","occ":"arafah","on":"نعم"},{"n":202,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَا مِنْ يَوْمٍ أَكْثَرَ مِنْ أَنْ يُعْتِقَ اللَّهُ فِيهِ عَبْدًا مِنَ النَّارِ مِنْ يَوْمِ عَرَفَةَ","nar":"عن عائشة رضي الله عنها","src":"رواه مسلم (1348)","grade":"","occ":"arafah","on":"نعم"},{"n":203,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ حَجَّ لِلَّهِ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1521) ومسلم (1350)","grade":"","occ":"dhulhijja_ten","on":"نعم"},{"n":204,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَيَّامُ التَّشْرِيقِ أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرٍ لِلَّهِ","nar":"عن نُبيشة الهذلي رضي الله عنه","src":"رواه مسلم (1141)","grade":"","occ":"eid_adha","on":"نعم"},{"n":205,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ، ثُمَّ نَرْجِعَ فَنَنْحَرَ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ أَصَابَ سُنَّتَنَا","nar":"عن البراء بن عازب رضي الله عنه","src":"رواه البخاري (965) ومسلم (1961)","grade":"","occ":"eid_adha","on":"نعم"},{"n":206,"cat":"العبادات والأركان","head":"عن أنس رضي الله عنه قال","text":"كَانَ رَسُولُ اللَّهِ ﷺ لَا يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ تَمَرَاتٍ، وَيَأْكُلُهُنَّ وِتْرًا","nar":"","src":"رواه البخاري (953)","grade":"","occ":"eid_fitr","on":"نعم"},{"n":207,"cat":"العبادات والأركان","head":"عن جابر رضي الله عنه قال","text":"كَانَ النَّبِيُّ ﷺ إِذَا كَانَ يَوْمُ عِيدٍ خَالَفَ الطَّرِيقَ","nar":"","src":"رواه البخاري (986)","grade":"","occ":"eid_fitr,eid_adha","on":"نعم"},{"n":208,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ؛ فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُدْخِلَ الْجَنَّةَ، وَفِيهِ أُخْرِجَ مِنْهَا، وَلَا تَقُومُ السَّاعَةُ إِلَّا فِي يَوْمِ الْجُمُعَةِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (854)","grade":"","occ":"friday","on":"نعم"},{"n":209,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ","nar":"عن أوس بن أوس رضي الله عنه","src":"رواه أبو داود (1047) والنسائي (1374)","grade":"صحيح","occ":"friday","on":"نعم"},{"n":210,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"فِي الْجُمُعَةِ سَاعَةٌ لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ وَهُوَ قَائِمٌ يُصَلِّي يَسْأَلُ اللَّهَ شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (935) ومسلم (852)","grade":"","occ":"friday","on":"نعم"},{"n":211,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ قَرَأَ سُورَةَ الْكَهْفِ يَوْمَ الْجُمُعَةِ أَضَاءَ لَهُ مِنَ النُّورِ مَا بَيْنَ الْجُمُعَتَيْنِ","nar":"عن أبي سعيد الخدري رضي الله عنه","src":"رواه الحاكم (3392) والبيهقي","grade":"صحيح","occ":"friday","on":"نعم"},{"n":212,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنِ اغْتَسَلَ ثُمَّ أَتَى الْجُمُعَةَ فَصَلَّى مَا قُدِّرَ لَهُ، ثُمَّ أَنْصَتَ حَتَّى يَفْرُغَ مِنْ خُطْبَتِهِ، ثُمَّ يُصَلِّي مَعَهُ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى وَفَضْلُ ثَلَاثَةِ أَيَّامٍ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (857)","grade":"","occ":"friday","on":"نعم"},{"n":213,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ","nar":"عن علي بن أبي طالب رضي الله عنه","src":"رواه الترمذي (3546)","grade":"صحيح","occ":"","on":"نعم"},{"n":214,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"وَاللَّهِ إِنِّي لَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6307)","grade":"","occ":"","on":"نعم"},{"n":215,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ: أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ، غُفِرَ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ","nar":"عن زيد مولى النبي ﷺ","src":"رواه أبو داود (1517) والترمذي (3577)","grade":"صحيح","occ":"","on":"نعم"},{"n":216,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، فِي يَوْمٍ مِائَةَ مَرَّةٍ، حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6405) ومسلم (2691)","grade":"","occ":"morning","on":"نعم"},{"n":217,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"لَأَنْ أَقُولَ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2695)","grade":"","occ":"","on":"نعم"},{"n":218,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ، أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ؟ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","nar":"عن أبي موسى الأشعري رضي الله عنه","src":"رواه البخاري (4205) ومسلم (2704)","grade":"","occ":"","on":"نعم"},{"n":219,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ، غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه الترمذي (3464)","grade":"صحيح","occ":"","on":"نعم"},{"n":220,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ، لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2692)","grade":"","occ":"morning,evening","on":"نعم"},{"n":221,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ، ثَلَاثَ مَرَّاتٍ، فَيَضُرَّهُ شَيْءٌ","nar":"عن عثمان بن عفان رضي الله عنه","src":"رواه أبو داود (5088) والترمذي (3388)","grade":"صحيح","occ":"morning,evening","on":"نعم"},{"n":222,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ نَزَلَ مَنْزِلًا ثُمَّ قَالَ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ، لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ","nar":"عن خولة بنت حكيم رضي الله عنها","src":"رواه مسلم (2708)","grade":"","occ":"evening","on":"نعم"},{"n":223,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ، فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللَّهُ لَهُ","nar":"عن سعد بن أبي وقاص رضي الله عنه","src":"رواه الترمذي (3505)","grade":"صحيح","occ":"","on":"نعم"},{"n":224,"cat":"الذكر والدعاء","head":"عن أنس رضي الله عنه قال","text":"كَانَ أَكْثَرُ دُعَاءِ النَّبِيِّ ﷺ: اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ","nar":"","src":"رواه البخاري (6389) ومسلم (2690)","grade":"","occ":"","on":"نعم"},{"n":225,"cat":"الذكر والدعاء","head":"عن أنس رضي الله عنه قال","text":"كَانَ رَسُولُ اللَّهِ ﷺ يُكْثِرُ أَنْ يَقُولَ: يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ","nar":"","src":"رواه الترمذي (2140)","grade":"صحيح","occ":"","on":"نعم"},{"n":226,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"إِنَّ رَبَّكُمْ حَيِيٌّ كَرِيمٌ، يَسْتَحْيِي مِنْ عَبْدِهِ إِذَا رَفَعَ يَدَيْهِ إِلَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا","nar":"عن سلمان الفارسي رضي الله عنه","src":"رواه أبو داود (1488) والترمذي (3556)","grade":"صحيح","occ":"","on":"نعم"},{"n":227,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى، وَالتُّقَى، وَالْعَفَافَ، وَالْغِنَى","nar":"عن عبد الله بن مسعود رضي الله عنه","src":"رواه مسلم (2721)","grade":"","occ":"","on":"نعم"},{"n":228,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (6369)","grade":"","occ":"","on":"نعم"},{"n":229,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِيَ الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2720)","grade":"","occ":"","on":"نعم"},{"n":230,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"يَا مُعَاذُ، وَاللَّهِ إِنِّي لَأُحِبُّكَ، أُوصِيكَ يَا مُعَاذُ: لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","nar":"عن معاذ بن جبل رضي الله عنه","src":"رواه أبو داود (1522) والنسائي (1303)","grade":"صحيح","occ":"","on":"نعم"},{"n":231,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ دُبُرَ كُلِّ صَلَاةٍ مَكْتُوبَةٍ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الْجَنَّةِ إِلَّا أَنْ يَمُوتَ","nar":"عن أبي أمامة رضي الله عنه","src":"رواه النسائي في الكبرى (9848)","grade":"صحيح","occ":"","on":"نعم"},{"n":232,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"مَنْ سَبَّحَ اللَّهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَحَمِدَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَكَبَّرَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَقَالَ تَمَامَ الْمِائَةِ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، غُفِرَتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (597)","grade":"","occ":"","on":"نعم"},{"n":233,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ، لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ، وَلَا يَقْرَبُكَ شَيْطَانٌ حَتَّى تُصْبِحَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2311)","grade":"","occ":"","on":"نعم"},{"n":234,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ، إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (780)","grade":"","occ":"","on":"نعم"},{"n":235,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"يُقَالُ لِصَاحِبِ الْقُرْآنِ: اقْرَأْ وَارْتَقِ وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا، فَإِنَّ مَنْزِلَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَؤُهَا","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه أبو داود (1464) والترمذي (2914)","grade":"صحيح","occ":"","on":"نعم"},{"n":236,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"قُلْ هُوَ اللَّهُ أَحَدٌ تَعْدِلُ ثُلُثَ الْقُرْآنِ","nar":"عن أبي سعيد الخدري رضي الله عنه","src":"رواه البخاري (5013)","grade":"","occ":"","on":"نعم"},{"n":237,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"سُورَةٌ مِنَ الْقُرْآنِ ثَلَاثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ، وَهِيَ: تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه أبو داود (1400) والترمذي (2891)","grade":"حسن","occ":"","on":"نعم"},{"n":238,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه مسلم (809)","grade":"","occ":"friday","on":"نعم"},{"n":239,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا، وَيَضَعُ بِهِ آخَرِينَ","nar":"عن عمر بن الخطاب رضي الله عنه","src":"رواه مسلم (817)","grade":"","occ":"","on":"نعم"},{"n":240,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ غَيْرَهُ","nar":"عن زيد بن ثابت رضي الله عنه","src":"رواه أبو داود (3660) والترمذي (2656)","grade":"صحيح","occ":"","on":"نعم"},{"n":241,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2674)","grade":"","occ":"","on":"نعم"},{"n":242,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"فَوَاللَّهِ لَأَنْ يَهْدِيَ اللَّهُ بِكَ رَجُلًا وَاحِدًا خَيْرٌ لَكَ مِنْ أَنْ يَكُونَ لَكَ حُمْرُ النَّعَمِ","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه البخاري (3009) ومسلم (2406)","grade":"","occ":"","on":"نعم"},{"n":243,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ الْمُؤْمِنَ لَيُدْرِكُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ الْقَائِمِ","nar":"عن عائشة رضي الله عنها","src":"رواه أبو داود (4798)","grade":"صحيح","occ":"","on":"نعم"},{"n":244,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ خُلُقٍ حَسَنٍ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه أبو داود (4799) والترمذي (2002)","grade":"صحيح","occ":"","on":"نعم"},{"n":245,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ","nar":"عن عائشة رضي الله عنها","src":"رواه البخاري (6927) ومسلم (2165)","grade":"","occ":"","on":"نعم"},{"n":246,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"أَنَا زَعِيمٌ بِبَيْتٍ فِي رَبَضِ الْجَنَّةِ لِمَنْ تَرَكَ الْمِرَاءَ وَإِنْ كَانَ مُحِقًّا، وَبِبَيْتٍ فِي وَسَطِ الْجَنَّةِ لِمَنْ تَرَكَ الْكَذِبَ وَإِنْ كَانَ مَازِحًا، وَبِبَيْتٍ فِي أَعْلَى الْجَنَّةِ لِمَنْ حَسَّنَ خُلُقَهُ","nar":"عن أبي أمامة رضي الله عنه","src":"رواه أبو داود (4800)","grade":"حسن","occ":"","on":"نعم"},{"n":247,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الْجَنَّةَ","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه البخاري (6474)","grade":"","occ":"","on":"نعم"},{"n":248,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللَّهِ لَا يُلْقِي لَهَا بَالًا يَرْفَعُهُ اللَّهُ بِهَا دَرَجَاتٍ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (6478)","grade":"","occ":"","on":"نعم"},{"n":249,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"السَّلَامُ عَلَيْكُمْ: عَشْرٌ، وَرَحْمَةُ اللَّهِ: عِشْرُونَ، وَبَرَكَاتُهُ: ثَلَاثُونَ","nar":"عن عمران بن حصين رضي الله عنه","src":"رواه أبو داود (5195) والترمذي (2689)","grade":"صحيح","occ":"","on":"نعم"},{"n":250,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"مَنْ لَا يَرْحَمِ النَّاسَ لَا يَرْحَمْهُ اللَّهُ","nar":"عن جرير بن عبد الله رضي الله عنه","src":"رواه البخاري (7376) ومسلم (2319)","grade":"","occ":"","on":"نعم"},{"n":251,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ","nar":"عن أبي ذر رضي الله عنه","src":"رواه الترمذي (1956)","grade":"صحيح","occ":"","on":"نعم"},{"n":252,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ، يَلْتَقِيَانِ فَيُعْرِضُ هَذَا وَيُعْرِضُ هَذَا، وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ","nar":"عن أبي أيوب الأنصاري رضي الله عنه","src":"رواه البخاري (6077) ومسلم (2560)","grade":"","occ":"","on":"نعم"},{"n":253,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"أَلَا أُخْبِرُكُمْ بِأَفْضَلَ مِنْ دَرَجَةِ الصِّيَامِ وَالصَّلَاةِ وَالصَّدَقَةِ؟ قَالُوا: بَلَى، قَالَ: صَلَاحُ ذَاتِ الْبَيْنِ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه أبو داود (4919) والترمذي (2509)","grade":"صحيح","occ":"","on":"نعم"},{"n":254,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ حَتَّى يَرْجِعَ","nar":"عن ثوبان رضي الله عنه","src":"رواه مسلم (2568)","grade":"","occ":"","on":"نعم"},{"n":255,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ. قِيلَ: مَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: مَنْ أَدْرَكَ أَبَوَيْهِ عِنْدَ الْكِبَرِ، أَحَدَهُمَا أَوْ كِلَيْهِمَا، فَلَمْ يَدْخُلِ الْجَنَّةَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2551)","grade":"","occ":"","on":"نعم"},{"n":256,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"الْوَالِدُ أَوْسَطُ أَبْوَابِ الْجَنَّةِ، فَإِنْ شِئْتَ فَأَضِعْ ذَلِكَ الْبَابَ أَوِ احْفَظْهُ","nar":"عن أبي الدرداء رضي الله عنه","src":"رواه الترمذي (1900) وابن ماجه (3663)","grade":"صحيح","occ":"","on":"نعم"},{"n":257,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"الدُّنْيَا مَتَاعٌ، وَخَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه مسلم (1467)","grade":"","occ":"","on":"نعم"},{"n":258,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"مَنْ عَالَ جَارِيَتَيْنِ حَتَّى تَبْلُغَا جَاءَ يَوْمَ الْقِيَامَةِ أَنَا وَهُوَ. وَضَمَّ أَصَابِعَهُ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه مسلم (2631)","grade":"","occ":"","on":"نعم"},{"n":259,"cat":"الأسرة وصلة الرحم","head":"قال رسول الله ﷺ","text":"إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ يَحْتَسِبُهَا فَهُوَ لَهُ صَدَقَةٌ","nar":"عن أبي مسعود البدري رضي الله عنه","src":"رواه البخاري (55) ومسلم (1002)","grade":"","occ":"","on":"نعم"},{"n":260,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا، أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه مسلم (2734)","grade":"","occ":"","on":"نعم"},{"n":261,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"إِنَّكَ لَنْ تَدَعَ شَيْئًا لِلَّهِ عَزَّ وَجَلَّ إِلَّا بَدَّلَكَ اللَّهُ بِهِ مَا هُوَ خَيْرٌ لَكَ مِنْهُ","nar":"عن رجل من أهل البادية رضي الله عنه","src":"رواه أحمد (20739)","grade":"صحيح","occ":"","on":"نعم"},{"n":262,"cat":"المجتمع والأخوة","head":"قال رسول الله ﷺ","text":"انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا. قَالُوا: يَا رَسُولَ اللَّهِ، هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا؟ قَالَ: تَأْخُذُ فَوْقَ يَدَيْهِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه البخاري (2444)","grade":"","occ":"","on":"نعم"},{"n":263,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا، وَيُوَقِّرْ كَبِيرَنَا","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه الترمذي (1920) وأبو داود (4943)","grade":"صحيح","occ":"","on":"نعم"},{"n":264,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ يُحِبُّ الْعَبْدَ التَّقِيَّ، الْغَنِيَّ، الْخَفِيَّ","nar":"عن سعد بن أبي وقاص رضي الله عنه","src":"رواه مسلم (2965)","grade":"","occ":"","on":"نعم"},{"n":265,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"الدُّنْيَا سِجْنُ الْمُؤْمِنِ، وَجَنَّةُ الْكَافِرِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2956)","grade":"","occ":"","on":"نعم"},{"n":266,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِرًا مِنْهَا شَرْبَةَ مَاءٍ","nar":"عن سهل بن سعد رضي الله عنه","src":"رواه الترمذي (2320) وابن ماجه (4110)","grade":"صحيح","occ":"","on":"نعم"},{"n":267,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"قَدْ أَفْلَحَ مَنْ أَسْلَمَ، وَرُزِقَ كَفَافًا، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ","nar":"عن عبد الله بن عمرو رضي الله عنهما","src":"رواه مسلم (1054)","grade":"","occ":"","on":"نعم"},{"n":268,"cat":"العقيدة والإخلاص","head":"قال رسول الله ﷺ","text":"لَوْ أَنَّكُمْ كُنْتُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرُزِقْتُمْ كَمَا تُرْزَقُ الطَّيْرُ، تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا","nar":"عن عمر بن الخطاب رضي الله عنه","src":"رواه الترمذي (2344) وابن ماجه (4164)","grade":"صحيح","occ":"morning","on":"نعم"},{"n":269,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ، حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا","nar":"عن أبي موسى الأشعري رضي الله عنه","src":"رواه مسلم (2759)","grade":"","occ":"","on":"نعم"},{"n":270,"cat":"الرقائق والتزكية","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ يَقْبَلُ تَوْبَةَ الْعَبْدِ مَا لَمْ يُغَرْغِرْ","nar":"عن عبد الله بن عمر رضي الله عنهما","src":"رواه الترمذي (3537) وابن ماجه (4253)","grade":"حسن","occ":"","on":"نعم"},{"n":271,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ فيما يرويه عن ربه عز وجل","text":"أَنْفِقْ يَا ابْنَ آدَمَ أُنْفِقْ عَلَيْكَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (5352) ومسلم (993)","grade":"","occ":"","on":"نعم"},{"n":272,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلَانِ، فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الْآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1442) ومسلم (1010)","grade":"","occ":"morning","on":"نعم"},{"n":273,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى","nar":"عن حكيم بن حزام رضي الله عنه","src":"رواه البخاري (1427)","grade":"","occ":"","on":"نعم"},{"n":274,"cat":"الأخلاق والآداب","head":"قال رسول الله ﷺ","text":"الصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ","nar":"عن معاذ بن جبل رضي الله عنه","src":"رواه الترمذي (2616)","grade":"صحيح","occ":"","on":"نعم"},{"n":275,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ -وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبَ- فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ، ثُمَّ يُرَبِّيهَا لِصَاحِبِهِ كَمَا يُرَبِّي أَحَدُكُمْ فَلُوَّهُ، حَتَّى تَكُونَ مِثْلَ الْجَبَلِ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (1410) ومسلم (1014)","grade":"","occ":"","on":"نعم"},{"n":276,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه ابن ماجه (224)","grade":"صحيح","occ":"","on":"نعم"},{"n":277,"cat":"القرآن والعلم","head":"قال رسول الله ﷺ","text":"إِنَّ اللَّهَ وَمَلَائِكَتَهُ وَأَهْلَ السَّمَوَاتِ وَالْأَرْضِ، حَتَّى النَّمْلَةَ فِي جُحْرِهَا، وَحَتَّى الْحُوتَ، لَيُصَلُّونَ عَلَى مُعَلِّمِ النَّاسِ الْخَيْرَ","nar":"عن أبي أمامة الباهلي رضي الله عنه","src":"رواه الترمذي (2685)","grade":"صحيح","occ":"","on":"نعم"},{"n":278,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا","nar":"عن أبي هريرة رضي الله عنه","src":"رواه الترمذي (3599) وابن ماجه (251)","grade":"صحيح","occ":"","on":"نعم"},{"n":279,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا","nar":"عن زيد بن أرقم رضي الله عنه","src":"رواه مسلم (2722)","grade":"","occ":"","on":"نعم"},{"n":280,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ","nar":"عن عبد الله بن عمر رضي الله عنهما","src":"رواه مسلم (2739)","grade":"","occ":"","on":"نعم"},{"n":281,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"سَلُوا اللَّهَ الْعَفْوَ وَالْعَافِيَةَ، فَإِنَّ أَحَدًا لَمْ يُعْطَ بَعْدَ الْيَقِينِ خَيْرًا مِنَ الْعَافِيَةِ","nar":"عن أبي بكر الصديق رضي الله عنه","src":"رواه الترمذي (3558) وأحمد (5)","grade":"صحيح","occ":"","on":"نعم"},{"n":282,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"طُوبَى لِمَنْ وَجَدَ فِي صَحِيفَتِهِ اسْتِغْفَارًا كَثِيرًا","nar":"عن عبد الله بن بسر رضي الله عنه","src":"رواه ابن ماجه (3818)","grade":"صحيح","occ":"","on":"نعم"},{"n":283,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"أَحَبُّ الْكَلَامِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ","nar":"عن سمرة بن جندب رضي الله عنه","src":"رواه مسلم (2137)","grade":"","occ":"","on":"نعم"},{"n":284,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"أَفْضَلُ الذِّكْرِ: لَا إِلَهَ إِلَّا اللَّهُ، وَأَفْضَلُ الدُّعَاءِ: الْحَمْدُ لِلَّهِ","nar":"عن جابر بن عبد الله رضي الله عنهما","src":"رواه الترمذي (3383) وابن ماجه (3800)","grade":"حسن","occ":"","on":"نعم"},{"n":285,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"سَبَقَ الْمُفَرِّدُونَ. قَالُوا: وَمَا الْمُفَرِّدُونَ يَا رَسُولَ اللَّهِ؟ قَالَ: الذَّاكِرُونَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (2676)","grade":"","occ":"","on":"نعم"},{"n":286,"cat":"الذكر والدعاء","head":"قال رسول الله ﷺ","text":"لَا يَقْعُدُ قَوْمٌ يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ إِلَّا حَفَّتْهُمُ الْمَلَائِكَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَنَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ","nar":"عن أبي هريرة وأبي سعيد رضي الله عنهما","src":"رواه مسلم (2700)","grade":"","occ":"","on":"نعم"},{"n":287,"cat":"الذكر والدعاء","head":"عن أبي هريرة رضي الله عنه قال: كان رسول الله ﷺ إذا أصبح قال","text":"اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ","nar":"","src":"رواه أبو داود (5068) والترمذي (3391)","grade":"صحيح","occ":"morning","on":"نعم"},{"n":288,"cat":"الذكر والدعاء","head":"عن حذيفة رضي الله عنه قال: كان النبي ﷺ إذا أخذ مضجعه من الليل قال","text":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا. وَإِذَا اسْتَيْقَظَ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","nar":"","src":"رواه البخاري (6312)","grade":"","occ":"","on":"نعم"},{"n":289,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"لَئِنْ بَقِيتُ إِلَى قَابِلٍ لَأَصُومَنَّ التَّاسِعَ","nar":"عن ابن عباس رضي الله عنهما","src":"رواه مسلم (1134)","grade":"","occ":"ashura","on":"نعم"},{"n":290,"cat":"العبادات والأركان","head":"عن أبي هريرة رضي الله عنه قال","text":"أَوْصَانِي خَلِيلِي ﷺ بِثَلَاثٍ: صِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَرَكْعَتَيِ الضُّحَى، وَأَنْ أُوتِرَ قَبْلَ أَنْ أَنَامَ","nar":"","src":"رواه البخاري (1981) ومسلم (721)","grade":"","occ":"white_days","on":"نعم"},{"n":291,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَلَّى الْغَدَاةَ فِي جَمَاعَةٍ، ثُمَّ قَعَدَ يَذْكُرُ اللَّهَ حَتَّى تَطْلُعَ الشَّمْسُ، ثُمَّ صَلَّى رَكْعَتَيْنِ، كَانَتْ لَهُ كَأَجْرِ حَجَّةٍ وَعُمْرَةٍ، تَامَّةٍ تَامَّةٍ تَامَّةٍ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه الترمذي (586)","grade":"حسن","occ":"morning","on":"نعم"},{"n":292,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ","nar":"عن جندب بن عبد الله رضي الله عنه","src":"رواه مسلم (657)","grade":"","occ":"morning","on":"نعم"},{"n":293,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"أَلَا أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ، فَذَلِكُمُ الرِّبَاطُ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه مسلم (251)","grade":"","occ":"","on":"نعم"},{"n":294,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُسْبِغُ الْوُضُوءَ، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ","nar":"عن عمر بن الخطاب رضي الله عنه","src":"رواه مسلم (234)","grade":"","occ":"","on":"نعم"},{"n":295,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"إِنَّ أَوَّلَ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ مِنْ عَمَلِهِ صَلَاتُهُ، فَإِنْ صَلَحَتْ فَقَدْ أَفْلَحَ وَأَنْجَحَ، وَإِنْ فَسَدَتْ فَقَدْ خَابَ وَخَسِرَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه الترمذي (413) والنسائي (465)","grade":"صحيح","occ":"","on":"نعم"},{"n":296,"cat":"العبادات والأركان","head":"قال رسول الله ﷺ","text":"حُبِّبَ إِلَيَّ مِنَ الدُّنْيَا النِّسَاءُ وَالطِّيبُ، وَجُعِلَتْ قُرَّةُ عَيْنِي فِي الصَّلَاةِ","nar":"عن أنس بن مالك رضي الله عنه","src":"رواه النسائي (3939)","grade":"صحيح","occ":"","on":"نعم"},{"n":297,"cat":"الحلال والحرام والورع","head":"قال رسول الله ﷺ","text":"لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا يُبَالِي الْمَرْءُ بِمَا أَخَذَ الْمَالَ، أَمِنْ حَلَالٍ أَمْ مِنْ حَرَامٍ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه البخاري (2083)","grade":"","occ":"","on":"نعم"},{"n":298,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ","nar":"عن أبي اليسر رضي الله عنه","src":"رواه مسلم (3006)","grade":"","occ":"","on":"نعم"},{"n":299,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"مَنِ اقْتَطَعَ شِبْرًا مِنَ الْأَرْضِ ظُلْمًا طَوَّقَهُ اللَّهُ إِيَّاهُ يَوْمَ الْقِيَامَةِ مِنْ سَبْعِ أَرَضِينَ","nar":"عن سعيد بن زيد رضي الله عنه","src":"رواه مسلم (1610)","grade":"","occ":"","on":"نعم"},{"n":300,"cat":"القضاء والمعاملات","head":"قال رسول الله ﷺ","text":"أَدِّ الْأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ، وَلَا تَخُنْ مَنْ خَانَكَ","nar":"عن أبي هريرة رضي الله عنه","src":"رواه أبو داود (3535) والترمذي (1264)","grade":"صحيح","occ":"","on":"نعم"}];
